package gamedata

import (
	"math"
	"sync"
)

// Static obstacles of the open world (trees, rocks, buildings), used by the server to keep mobs from walking
// through them and to block shots without line of sight.
//
// The tree/rock layout is generated by the client (Client/js/world/vegetation.js) from a seeded random
// sequence. collideVegetation below is an exact port of that placement loop so both sides agree on where
// the obstacles stand. If you change the placement in the client, change it here too (see TestVegetationCount).

type solidCircle struct {
	x, z, r float64
	los     bool // thick enough to block line of sight (trees, rocks), not bushes
}
type solidBox struct{ x, z, hw, hd float64 }

var (
	collOnce  sync.Once
	circles   map[[2]int][]solidCircle // 8x8 cells
	boxes     []solidBox
	boxCircle map[[2]int][]int // 8x8 cells -> indices into boxes
)

func cellKey(x, z float64) [2]int { return [2]int{int(math.Floor(x / 8)), int(math.Floor(z / 8))} }

func initColliders() {
	collOnce.Do(func() {
		sc := BuildScenery()
		circles = map[[2]int][]solidCircle{}
		boxCircle = map[[2]int][]int{}
		for _, b := range sc.House {
			boxes = append(boxes, solidBox{b.X, b.Z, b.W / 2, b.D / 2})
		}
		for _, b := range sc.Buildings {
			switch b.Kind {
			case "pad", "dock", "ship", "lantern", "pond", "gate":
				continue
			case "tent":
				b.W, b.D = b.W*0.9, b.D*0.9
			}
			boxes = append(boxes, solidBox{b.X, b.Z, b.W / 2, b.D / 2})
		}
		for i, b := range boxes {
			for cx := int(math.Floor((b.x - b.hw - 1) / 8)); cx <= int(math.Floor((b.x+b.hw+1)/8)); cx++ {
				for cz := int(math.Floor((b.z - b.hd - 1) / 8)); cz <= int(math.Floor((b.z+b.hd+1)/8)); cz++ {
					boxCircle[[2]int{cx, cz}] = append(boxCircle[[2]int{cx, cz}], i)
				}
			}
		}
		collideVegetation(sc)
	})
}

// quantised grid access exactly as the client sees it (int16 of h*20, stored as float32)
func qHeight(i, j int) float64 {
	i = max(0, min(GridNX-1, i))
	j = max(0, min(GridNZ-1, j))
	return float64(float32(float64(int16(math.Round(float64(hm[j*GridNX+i])*20))) / 20))
}

func qHeightAt(x, z float64) float64 {
	gx, gz := (x-WorldMinX)/GridCell, (z-WorldMinZ)/GridCell
	i, j := int(math.Floor(gx)), int(math.Floor(gz))
	fx, fz := gx-float64(i), gz-float64(j)
	a, b, c, d := qHeight(i, j), qHeight(i+1, j), qHeight(i, j+1), qHeight(i+1, j+1)
	return a + (b-a)*fx + (c-a)*fz + (a-b-c+d)*fx*fz
}

func collideVegetation(sc Scenery) {
	seed := uint32(2024)
	r := func() float64 { seed = seed*1664525 + 1013904223; return float64(seed) / 4294967296 }
	const step = 3.0
	blocked := func(x, z float64) bool {
		for _, c := range sc.Clears {
			if math.Hypot(x-c.X, z-c.Z) < c.R+1.2 {
				return true
			}
		}
		for _, rd := range sc.Roads {
			if distToPoly(x, z, rd) < 3.2 {
				return true
			}
		}
		for _, b := range sc.Buildings {
			if b.Kind != "wall" && math.Abs(x-b.X) < b.W/2+2 && math.Abs(z-b.Z) < b.D/2+2 {
				return true
			}
		}
		for _, b := range sc.House {
			if math.Abs(x-b.X) < b.W/2+3 && math.Abs(z-b.Z) < b.D/2+3 {
				return true
			}
		}
		return false
	}
	add := func(x, z, sc, solid float64) {
		r() // the client draws a random rotation for every placed object
		if solid > 0 {
			k := cellKey(x, z)
			circles[k] = append(circles[k], solidCircle{x, z, solid * sc, solid >= 0.5})
		}
	}
	xEnd := WorldMinX + float64(GridNX-1)*GridCell - 4
	zEnd := WorldMinZ + float64(GridNZ-1)*GridCell - 4
	for z := WorldMinZ + 4; z < zEnd; z += step {
		for x := WorldMinX + 4; x < xEnd; x += step {
			px, pz := x+(r()-0.5)*step, z+(r()-0.5)*step
			b := int(qBiome(px, pz))
			if b == 0 || b == 10 {
				continue
			}
			h := qHeightAt(px, pz)
			if h < 0.35 {
				if b == 3 && h > -1.0 && h < 0.35 && r() < 0.12 && !blocked(px, pz) {
					r() // scale of the reed
					add(px, pz, 0, 0)
				}
				continue
			}
			if r() > 0.5 {
				continue
			}
			if blocked(px, pz) {
				continue
			}
			slope := math.Abs(qHeightAt(px+2, pz)-h) + math.Abs(qHeightAt(px, pz+2)-h)
			s := 0.8 + r()*0.9
			u := r()
			switch b {
			case 1:
				if u < 0.55 {
					r()
					add(px, pz, s, 0.5)
				} else if u < 0.62 {
					add(px, pz, s, 0.4)
				} else if u < 0.66 {
					add(px, pz, s*0.8, 0.6)
				} else {
					add(px, pz, s, 0)
				}
			case 2:
				if u < 0.08 {
					add(px, pz, s, 0.5)
				} else if u < 0.12 {
					add(px, pz, s, 0.4)
				} else if u < 0.55 {
					add(px, pz, s, 0)
				}
			case 3:
				if u < 0.22 {
					add(px, pz, s, 0.4)
				} else if u < 0.32 {
					add(px, pz, s, 0)
				} else if u < 0.38 {
					add(px, pz, s, 0.4)
				} else if u < 0.55 {
					add(px, pz, s, 0)
				}
			case 4:
				if h > 24 || slope > 3.2 {
					if u < 0.25 {
						add(px, pz, s*1.4, 0.9)
					}
				} else if u < 0.30 {
					add(px, pz, s, 0.5)
				} else if u < 0.34 {
					add(px, pz, s*1.1, 0.8)
				}
			case 5:
				if u < 0.06 {
					add(px, pz, s, 0.5)
				} else if u < 0.085 {
					add(px, pz, s, 0.7)
				} else if u < 0.10 && h < 1.8 {
					add(px, pz, s, 0.4)
				} else if u < 0.105 {
					add(px, pz, s, 0)
				} else if u < 0.15 {
					add(px, pz, s*0.7, 0)
				}
			case 6:
				if u < 0.46 {
					add(px, pz, s*1.05, 0.7)
				} else if u < 0.51 && h < 2.2 {
					add(px, pz, s, 0.4)
				} else if u < 0.68 {
					add(px, pz, s, 0)
				} else if u < 0.76 {
					add(px, pz, s*0.9, 0.4)
				} else if u < 0.82 {
					add(px, pz, s, 0.4)
				} else if u < 0.88 {
					add(px, pz, s, 0)
				} else if u < 0.9 {
					add(px, pz, s, 0.6)
				}
			case 7:
				if u < 0.2 {
					add(px, pz, s, 0.5)
				} else if u < 0.28 {
					add(px, pz, s, 0.4)
				} else if u < 0.32 {
					add(px, pz, s*0.8, 0.4)
				} else if u < 0.34 {
					add(px, pz, s*0.8, 0.6)
				} else if u < 0.72 {
					add(px, pz, s, 0)
				}
			case 8:
				if u < 0.045 && slope < 2.5 {
					add(px, pz, s*1.2, 1.3)
				} else if u < 0.12 {
					add(px, pz, s*1.1, 0.8)
				} else if u < 0.16 {
					add(px, pz, s, 0.5)
				} else if u < 0.28 {
					add(px, pz, s, 0)
				}
			case 9:
				if u < 0.12 && slope < 3 {
					add(px, pz, s, 0.4)
				} else if u < 0.25 {
					add(px, pz, s*1.2, 0.8)
				} else if u < 0.32 {
					add(px, pz, s, 0.7)
				} else if u < 0.36 {
					add(px, pz, s, 0)
				}
			}
		}
	}
}

func qBiome(x, z float64) Biome {
	i := max(0, min(GridNX-1, int(math.Round((x-WorldMinX)/GridCell))))
	j := max(0, min(GridNZ-1, int(math.Round((z-WorldMinZ)/GridCell))))
	return Biome(bm[j*GridNX+i])
}

// ---- queries ----

// Collide pushes a body of radius rad out of trees, rocks and buildings (open world only).
func Collide(x, z, rad float64) (float64, float64) {
	if z > DungeonZ0-100 {
		return x, z
	}
	initColliders()
	gx, gz := int(math.Floor(x/8)), int(math.Floor(z/8))
	for ix := gx - 1; ix <= gx+1; ix++ {
		for iz := gz - 1; iz <= gz+1; iz++ {
			for _, c := range circles[[2]int{ix, iz}] {
				dx, dz := x-c.x, z-c.z
				d := math.Hypot(dx, dz)
				if m := c.r + rad; d < m && d > 1e-4 {
					x, z = c.x+dx/d*m, c.z+dz/d*m
				}
			}
		}
	}
	for _, i := range boxCircle[[2]int{gx, gz}] {
		b := boxes[i]
		hx, hz := b.hw+rad, b.hd+rad
		dx, dz := x-b.x, z-b.z
		if math.Abs(dx) < hx && math.Abs(dz) < hz {
			px, pz := hx-math.Abs(dx), hz-math.Abs(dz)
			if px < pz {
				x = b.x + math.Copysign(hx, dx+1e-9)
			} else {
				z = b.z + math.Copysign(hz, dz+1e-9)
			}
		}
	}
	return x, z
}

// LineBlocked reports whether the straight line between two points is cut by a building (and, with trees,
// also by tree trunks and rocks). Used for line of sight.
func LineBlocked(x0, z0, x1, z1 float64, trees bool) bool {
	if z0 > DungeonZ0-100 {
		return false
	}
	initColliders()
	n := int(math.Ceil(math.Hypot(x1-x0, z1-z0) / 0.7))
	for i := 1; i < n; i++ { // end points themselves are never blocked
		t := float64(i) / float64(n)
		x, z := x0+(x1-x0)*t, z0+(z1-z0)*t
		k := cellKey(x, z)
		for _, bi := range boxCircle[k] {
			b := boxes[bi]
			if math.Abs(x-b.x) < b.hw && math.Abs(z-b.z) < b.hd {
				return true
			}
		}
		if !trees {
			continue
		}
		for cx := k[0] - 1; cx <= k[0]+1; cx++ {
			for cz := k[1] - 1; cz <= k[1]+1; cz++ {
				for _, c := range circles[[2]int{cx, cz}] {
					if c.los && math.Hypot(x-c.x, z-c.z) < c.r*0.6 {
						return true
					}
				}
			}
		}
	}
	return false
}

// VegetationCount is used by tests to compare against the client's layout.
func VegetationCount() (n int) {
	initColliders()
	for _, c := range circles {
		n += len(c)
	}
	return
}
